-- patch_charge_1a_reglees_2026-11-24 -- les controles, rejouables. AUCUNE ECRITURE.
select 'charge_1a_reglees_2026-11-24' as lot, (select count(*) from public.app_classeur_realignement_journal where lot = 'charge_1a_reglees_2026-11-24') as au_journal, (select md5(coalesce(string_agg(concat_ws('|', m.annonce, m.numero, coalesce(k.valeur_app, '-'), coalesce(k.origine, '-'), coalesce(k.ecrit_par, '-'), coalesce(r.mandat_charge_honoraires_app, '-')), ';' order by m.annonce, m.numero), '')) from (values ('47542', '17840'), ('23297', '17564'), ('17548', '17481')) m(annonce, numero) left join public.app_mandat_champ_app k on k.hektor_annonce_id = m.annonce and k.numero_mandat = m.numero and k.champ = 'charge_commission' left join public.app_mandat_register_current r on r.hektor_annonce_id::text = m.annonce and r.numero_mandat::text = m.numero) as empreinte, '04f45cf7db6dfb1617d27ce972f9810f' as attendue;
